from django.utils.text import slugify


def company_named(model, name):
    """Existing company with this name (case-insensitive), else a new one with a unique slug."""
    existing = model.objects.filter(name__iexact=name).first()
    if existing:
        return existing
    base = slugify(name)[:120] or "company"
    slug, suffix = base, 1
    while model.objects.filter(slug=slug).exists():
        suffix += 1
        slug = f"{base}-{suffix}"
    return model.objects.create(name=name, slug=slug)


def reseller_to_companies(apps, schema_editor):
    """Preserve free-text resellers: TPM contracts get a maintenance company, all others an integrator."""
    SupportContract = apps.get_model("netbox_support_contracts", "SupportContract")
    Integrator = apps.get_model("netbox_support_contracts", "Integrator")
    MaintenanceCompany = apps.get_model("netbox_support_contracts", "MaintenanceCompany")
    for contract in SupportContract.objects.exclude(reseller="").order_by("pk"):
        name = contract.reseller.strip()[:128]
        if not name:
            continue
        if contract.contract_type == "tpm":
            contract.maintenance_company = company_named(MaintenanceCompany, name)
            contract.save(update_fields=["maintenance_company"])
        else:
            contract.integrator = company_named(Integrator, name)
            contract.save(update_fields=["integrator"])


def companies_to_reseller(apps, schema_editor):
    """Reverse: copy the linked company name back into the free-text reseller field."""
    SupportContract = apps.get_model("netbox_support_contracts", "SupportContract")
    contracts = SupportContract.objects.select_related("integrator", "maintenance_company")
    for contract in contracts.filter(models.Q(integrator__isnull=False) | models.Q(maintenance_company__isnull=False)):
        if contract.contract_type == "tpm" and contract.maintenance_company:
            company = contract.maintenance_company
        else:
            company = contract.integrator or contract.maintenance_company
        contract.reseller = company.name[:128]
        contract.save(update_fields=["reseller"])

